import { doc, getDoc, onSnapshot, setDoc, type Firestore } from 'firebase/firestore';
import type { User } from 'firebase/auth';
import { getFirestoreDb } from '../firebaseService';
import { logService } from "../logService.svelte";
import { rewardsState } from '$lib/stores/rewardsState.svelte';
import { versionState } from '$lib/stores/versionState.svelte';
import { storageService } from '../storage';
import { userProfileStore, type UserProfile } from '$lib/stores/authState.svelte';

// `UserProfile` оголошений разом зі станом; тут лише ре-експорт для сумісності.
export type { UserProfile } from '$lib/stores/authState.svelte';

const getInitialProfile = (): UserProfile => {
    if (typeof window === 'undefined') {
        return { uid: 'local', displayName: null, bestTimeScore: 0, isAnonymous: true };
    }
    const localName = storageService.get('online_playerName');
    const displayName = (localName === 'Player' || !localName) ? null : localName;

    return {
        uid: 'local',
        displayName: displayName,
        bestTimeScore: parseInt(storageService.get('local_best_time_score') || '0'),
        isAnonymous: true
    };
};

/*
 * Стан живе у `$lib/stores/authState.svelte.ts` (§ 10.4: SDK і реактивний
 * модуль не змішуються). Тут — мережа: Firestore. Початкове значення
 * виставляється звідси, бо `getInitialProfile()` читає локальне сховище, а це
 * теж робота сервісу, не стану.
 */
export { userProfileStore } from '$lib/stores/authState.svelte';

// Початкове значення — з локального сховища, один раз на завантаження модуля.
userProfileStore.profile = getInitialProfile();

class UserProfileService {
    private db: Firestore;
    /** Зняття живої підписки. `null` — її немає. */
    private unwatch: (() => void) | null = null;

    constructor() {
        this.db = getFirestoreDb();
    }

    async syncUserProfile(user: User) {
        const userRef = doc(this.db, 'users', user.uid);

        rewardsState.syncWithCloud(user.uid);

        try {
            const snap = await getDoc(userRef);

            const localBest = parseInt(storageService.get('local_best_time_score') || '0');
            const localNameRaw = storageService.get('online_playerName');
            const localName = (localNameRaw === 'Player') ? null : localNameRaw;

            if (snap.exists()) {
                const data = snap.data();
                const cloudBest = data.bestTimeScore || 0;
                const cloudName = data.displayName || null;

                const finalBest = Math.max(localBest, cloudBest);

                const updates: any = { lastActive: Date.now() };
                if (localBest > cloudBest) updates.bestTimeScore = localBest;

                if (!cloudName && localName) updates.displayName = localName;

                await setDoc(userRef, updates, { merge: true });

                if (cloudBest > localBest) {
                    storageService.set('local_best_time_score', cloudBest.toString());
                }
                if (cloudName) {
                    storageService.set('online_playerName', cloudName);
                }

                userProfileStore.profile = ({
                    uid: user.uid,
                    displayName: cloudName || localName,
                    bestTimeScore: finalBest,
                    isAnonymous: user.isAnonymous
                });
            } else {
                const currentVersion = versionState.state.current;
                const initialData = {
                    displayName: localName,
                    bestTimeScore: localBest,
                    createdAt: Date.now(),
                    lastActive: Date.now(),
                    createdVersion: currentVersion || 'unknown'
                };
                await setDoc(userRef, initialData);

                userProfileStore.profile = ({
                    uid: user.uid,
                    displayName: localName,
                    bestTimeScore: localBest,
                    isAnonymous: user.isAnonymous
                });
            }
        } catch (e) {
            logService.error('[UserProfileService] Sync profile failed', e);
            const localBest = parseInt(storageService.get('local_best_time_score') || '0');
            const localName = storageService.get('online_playerName');

            userProfileStore.profile = ({
                uid: user.uid,
                displayName: localName === 'Player' ? null : localName,
                bestTimeScore: localBest,
                isAnonymous: user.isAnonymous
            });
        }
    }

    /**
     * ЖИВА ПІДПИСКА на свій документ — рекорд із другого пристрою доїжджає САМ.
     *
     * ## Що було не так
     *
     * `syncUserProfile` кликався рівно один раз — на зміну стану входу. Тобто
     * рекорд, поставлений на телефоні, зʼявлявся на ноутбуці лише при наступному
     * відкритті сторінки: «синхронізація між пристроями» означала «наступного
     * разу». Сусідній `Slovko` тримає живий `onSnapshot` саме з цієї причини.
     *
     * ## Злиття МАКСИМУМОМ, а не заміною
     *
     * Прийшло більше — беремо хмарне; місцеве більше — відсилаємо своє. Максимум
     * ІДЕМПОТЕНТНИЙ: підписка спрацьовує й на власний запис, і повторне злиття
     * того самого не міняє нічого. Сума на цьому місці давала б рекорд, який
     * росте від самого факту синхронізації.
     *
     * ## Одна підписка на застосунок
     *
     * Друга давала б два злиття на кожну зміну й два записи назад, тож попередня
     * знімається тут же. Повертається зняття — його кличе `authService` при зміні
     * користувача: слухач, що переживе вихід з акаунта, читав би чужий документ.
     *
     * НАГОРОДИ тут не слухаються: вони лише додаються, злиття їх обʼєднує, і
     * різниця «побачив нову нагороду зараз чи при наступному відкритті» не варта
     * другого слухача. Межа названа, щоб її не шукали як дефект.
     */
    watchUserProfile(uid: string): () => void {
        this.stopWatching();

        const userRef = doc(this.db, 'users', uid);
        this.unwatch = onSnapshot(
            userRef,
            (snap) => {
                if (!snap.exists()) return;
                const cloudBest = (snap.data().bestTimeScore as number) || 0;
                const localBest = parseInt(storageService.get('local_best_time_score') || '0');

                if (cloudBest > localBest) {
                    storageService.set('local_best_time_score', cloudBest.toString());
                    if (userProfileStore.profile) userProfileStore.profile.bestTimeScore = cloudBest;
                    logService.info('[UserProfileService] Best score arrived from another device');
                } else if (localBest > cloudBest) {
                    // Своє більше — відсилаємо. Інакше рекорд, поставлений офлайн,
                    // лишився б лише на цьому пристрої.
                    void setDoc(userRef, { bestTimeScore: localBest }, { merge: true }).catch(
                        (error: unknown) =>
                            logService.warn('[UserProfileService] Best score not sent', error)
                    );
                }
            },
            (error) => logService.error('[UserProfileService] Live sync failed', error)
        );

        return () => this.stopWatching();
    }

    /** Зняти підписку. Кличе `authService` на кожній зміні користувача. */
    stopWatching(): void {
        this.unwatch?.();
        this.unwatch = null;
    }

    async updateNickname(name: string, currentUser: User | null) {
        const nameToSave = (name && name.trim() !== '' && name !== 'Player') ? name : null;

        if (userProfileStore.profile) userProfileStore.profile.displayName = nameToSave;

        if (nameToSave) {
            storageService.set('online_playerName', nameToSave);
        } else {
            storageService.remove('online_playerName');
        }

        if (!currentUser) return;

        try {
            const { updateProfile } = await import('firebase/auth');
            await updateProfile(currentUser, { displayName: nameToSave });

            const userRef = doc(this.db, 'users', currentUser.uid);

            await setDoc(userRef, {
                displayName: nameToSave,
                lastActive: Date.now()
            }, { merge: true });

            logService.action(`[UserProfileService] Nickname updated to ${nameToSave}`);
        } catch (error) {
            logService.error('[UserProfileService] Update profile error', error);
        }
    }

    /**
     * Прибрати ХМАРНІ дані гравця — перед видаленням самого користувача.
     *
     * ## Що саме прибирається
     *
     * `users/{uid}` (рекорд і нікнейм), його підколекції підписок, `rewards/{uid}`,
     * публічний профіль `profiles/{uid}` і РЯДКИ ТАБЛИЦІ ЛІДЕРІВ. Останнє тут
     * головне: таблиця публічна, і доти рекорд видаленого акаунта лишався в ній
     * назавжди — імʼя людини, якої вже немає, показувалося всім, і прибрати його
     * не міг уже ніхто.
     *
     * ## Чому кожне — своїм власником
     *
     * Рядки таблиці прибирає `leaderboardService`, підписки — `friendsService`,
     * профіль — `profilesService`. Другий екземпляр того самого запиту тут
     * розійшовся б із першим на наступній правці; а `import()` замість
     * статичного імпорту рятує від кола `authService → userProfileService →
     * leaderboardService → authService`.
     *
     * НЕ КИДАЄ на окремому документі: видалення акаунта не мусить зупинятися
     * через один рядок, якого вже немає.
     */
    public async eraseCloudData(uid: string): Promise<void> {
        const [{ leaderboardService }, { eraseFollows }, { removeProfile }] = await Promise.all([
            import('../leaderboardService'),
            import('../social/friendsService'),
            import('../social/profilesService')
        ]);

        await leaderboardService.removeMyEntries(uid);
        await eraseFollows(uid);
        await removeProfile(uid).catch((error: unknown) => {
            logService.warn('[UserProfileService] Public profile not deleted', error);
        });

        const { deleteDoc } = await import('firebase/firestore');
        await Promise.all([
            deleteDoc(doc(this.db, 'users', uid)).catch((error: unknown) => {
                logService.warn('[UserProfileService] User doc not deleted', error);
            }),
            deleteDoc(doc(this.db, 'rewards', uid)).catch((error: unknown) => {
                logService.warn('[UserProfileService] Rewards doc not deleted', error);
            })
        ]);
    }

    public clearLocalUserData() {
        logService.init('[UserProfileService] Clearing local user data...');
        storageService.remove('local_best_time_score');
        storageService.remove('sotb_rewards');
        storageService.remove('online_playerName');
    }

    public resetLocalProfile() {
        userProfileStore.profile = ({
            uid: 'local',
            displayName: null,
            bestTimeScore: 0,
            isAnonymous: true
        });
    }
}

export const userProfileService = new UserProfileService();
